import json,sys
d=json.load(open('layout.json'))
def txt(n,ind=0):
    t=n.get('type')
    if t=='text': return n.get('text','')
    if t in ('codeVoice','strong','emphasis'): return ''.join(txt(c) for c in n.get('inlineContent',[]))
    if t=='reference': return n.get('title') or ''
    if t=='paragraph': return ''.join(txt(c) for c in n.get('inlineContent',[]))+'\n\n'
    if t=='heading': return '\n## '+n.get('text','')+'\n\n'
    if t in ('unorderedList','orderedList'):
        return ''.join('- '+''.join(txt(c) for c in i.get('content',[])).strip()+'\n' for i in n.get('items',[]))+'\n'
    if t=='aside':
        return '['+n.get('name','Note')+'] '+''.join(txt(c) for c in n.get('content',[]))+'\n'
    if 'content' in n: return ''.join(txt(c) for c in n['content'])
    if 'inlineContent' in n: return ''.join(txt(c) for c in n['inlineContent'])
    return ''
for sec in d.get('primaryContentSections',[]):
    for c in sec.get('content',[]):
        sys.stdout.write(txt(c))
print('=== ABSTRACT ===')
print(''.join(txt(c) for c in d.get('abstract',[])))
print('=== METADATA ===', json.dumps(d.get('metadata',{}))[:800])
