import json
d=json.load(open('layout.json'))
def flat(n):
    if isinstance(n,list): return ''.join(flat(x) for x in n)
    if isinstance(n,dict):
        if n.get('type')=='text': return n.get('text','')
        for k in ('inlineContent','content','items'):
            if k in n: return flat(n[k])
        return ''
    return ''
tabs=[c for sec in d.get('primaryContentSections',[]) for c in sec.get('content',[]) if c.get('type')=='table']
for i,t in enumerate(tabs):
    print('=== TABLE',i,len(t['rows']),'rows')
    for r in t['rows'][:12]:
        print(' | '.join(flat(c) for c in r))
